var _fade_tween: Tween
var _crossfade_tween: Tween

@onready var current_background: TextureRect = $CurrentBackground
@onready var crossfade_background: TextureRect = $CrossfadeBackground
@onready var black_overlay: ColorRect = $BlackOverlay


func _ready() -> void:
	crossfade_background.modulate.a = 0.0
	black_overlay.modulate.a = 0.0


func is_transitioning() -> bool:
	var crossfade_active := _crossfade_tween != null and _crossfade_tween.is_running()
	var fade_active := _fade_tween != null and _fade_tween.is_running()
	return crossfade_active or fade_active


func set_background(texture: Texture2D) -> void:
	if _crossfade_tween and _crossfade_tween.is_running():
		_crossfade_tween.kill()
	current_background.texture = texture
	crossfade_background.texture = null
	crossfade_background.modulate.a = 0.0


func crossfade_to(new_texture: Texture2D, duration: float = 0.5) -> void:
	if duration <= 0.0:
		set_background(new_texture)
		return

	if _crossfade_tween and _crossfade_tween.is_running():
		_crossfade_tween.kill()

	crossfade_background.texture = new_texture
	crossfade_background.modulate.a = 0.0

	_crossfade_tween = create_tween()
	_crossfade_tween.tween_property(crossfade_background, "modulate:a", 1.0, duration)
	await _crossfade_tween.finished

	current_background.texture = new_texture
	crossfade_background.texture = null
	crossfade_background.modulate.a = 0.0


func fade_to_black(duration: float = 0.5) -> void:
	if duration <= 0.0:
		black_overlay.modulate.a = 1.0
		return

	if _fade_tween and _fade_tween.is_running():
		_fade_tween.kill()

	_fade_tween = create_tween()
	_fade_tween.tween_property(black_overlay, "modulate:a", 1.0, duration)
	await _fade_tween.finished


func fade_from_black(duration: float = 0.5) -> void:
	if duration <= 0.0:
		black_overlay.modulate.a = 0.0
		return

	if _fade_tween and _fade_tween.is_running():
		_fade_tween.kill()

	_fade_tween = create_tween()
	_fade_tween.tween_property(black_overlay, "modulate:a", 0.0, duration)
	await _fade_tween.finished


func transition_through_black(new_texture: Texture2D, duration: float = 0.5) -> void:
	if duration <= 0.0:
		if _fade_tween and _fade_tween.is_running():
			_fade_tween.kill()
		black_overlay.modulate.a = 0.0
		set_background(new_texture)
		return

	var half_duration := duration * 0.5
	await fade_to_black(half_duration)
	set_background(new_texture)
	await fade_from_black(half_duration)

